import { OpenAPIRegistry, OpenApiGeneratorV3 } from '@asteasolutions/zod-to-openapi';
import { z } from 'zod';
const registry = new OpenAPIRegistry();
const User = registry.register('User', z.object({ id: z.string(), name: z.string() }));
registry.registerPath({
  method: 'get', path: '/users/{id}', summary: 'Get user',
  request: { params: z.object({ id: z.string() }) },
  responses: { 200: { description: 'ok', content: { 'application/json': { schema: User } } } }
});
const doc = new OpenApiGeneratorV3(registry.definitions).generateDocument({ openapi: '3.0.0', info: { title: 'api', version: '1' } });
